insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('51bbe6fd-2e21-43f0-a645-75daf7830d61', 'ce7fda7b-6761-4a3e-a790-ce2ae7385c71', $$bron 1: brief van Cincius Romanus over de bibliotheek van Sankt Gallen (1416)$$,
   $$geschiedenis-havo-2025-ii-ontdekkers-en-hervormers-bron1.png$$,
   $$bron 1 In 1416 reist de Italiaan Cincius Romanus naar het klooster Sankt Gallen in Zwitserland. Hij schrijft aan een vriend:
Maar toen we de toren van de kerk van Sankt Gallen zorgvuldig bestudeerden, daar waar talloze boeken worden bewaard als gevangenen en waar de bibliotheek verwaarloosd is en vol met stof, wormen, roet en allerlei andere zaken die worden geassocieerd met de vernietiging van boeken, barstten we in tranen uit. We bedachten dat dit de manier is waarop de Latijnse taal zijn grootse glorie en onderscheiding had verloren. Werkelijk, als deze bibliotheek kon spreken dan zou het uitroepen: "Jullie die de Latijnse taal zo liefhebben, zorg ervoor dat ik niet helemaal vernietigd raak door deze treurige verwaarlozing!"$$, 'inline'),
  ('ccd972df-c61a-4271-a5c9-b4930e6d64a5', '2baaeaa7-e8c2-44f1-9c30-8e173a0b6a88', $$bron 3: medaille van de East India Company voor inheemse soldaten (1784)$$,
   $$geschiedenis-havo-2025-ii-het-britse-rijk-bron3.png$$,
   $$bron 3 Een medaille uit 1784, uitgereikt door de East India Company:
[Afbeelding] Foto van een medaille: Brittannia zit met speer en schild tussen wapens en houdt een lauwerkrans omhoog; op de achtergrond een fort.
Toelichting: Op de medaille staat Brittannia, een symbool voor Groot-Brittannië. Brittannia houdt een lauwerkrans vast, een beloning voor overwinnaars. Op de achtergrond staat een Indiaas fort afgebeeld waarop de Britse vlag is gehesen.$$, 'inline'),
  ('224c081d-792d-4cbb-b942-f22c5f22934d', '2baaeaa7-e8c2-44f1-9c30-8e173a0b6a88', $$bron 6: tekening van een Brits schip op de Indus (1861)$$,
   $$geschiedenis-havo-2025-ii-het-britse-rijk-bron6.png$$,
   $$bron 6 Tekening uit 1861 van een Brits schip op de Indiase rivier de Indus:
[Afbeelding] Gravure: een lang, plat stoomschip met schoepenrad en drie schoorstenen vaart over een brede rivier; op de voorgrond een klein bootje.$$, 'inline'),
  ('2b08553a-7cd5-49e4-a1f8-e882201da4e0', '2baaeaa7-e8c2-44f1-9c30-8e173a0b6a88', $$bron 8: Brits lied over koloniale politiek in Afrika (rond 1895)$$,
   $$geschiedenis-havo-2025-ii-het-britse-rijk-bron8.png$$,
   $$bron 8 Rond 1895 wordt in Groot-Brittannië een lied geschreven over Britse koloniale politiek in Afrika:
Voorwaarts, huursoldaten, op naar het heidens land, Kerkboek in je zakken, ''t geweer klaar in je hand. Breng het goede bericht naar landen met een handelssfeer, Verbreid het vreedzaam evangelie – met een Maximgeweer1).
noot 1 Dit is een Brits machinegeweer.$$, 'inline'),
  ('c8f28811-cffc-45a5-b384-17a2432c1dfc', '3121c032-54c5-4142-ac93-daf56e79a885', $$bron 2: brief van WIC-bestuurder Pieter Schaghen over Nieuw-Nederland (1626)$$,
   $$geschiedenis-havo-2025-ii-regenten-en-vorsten-bron2.png$$,
   $$bron 2 Pieter Schaghen zit in het bestuur van de handelsorganisatie West-Indische Compagnie (WIC) te Amsterdam. Op 7 november 1626 schrijft hij:
Gister is het schip Het Wapen van Amsterdam gearriveerd. Het is vertrokken uit Nieuw-Nederland1) op 23 september. Ze brengen de boodschap dat het volk2) gezond is en in vrede leeft. De vrouwen hebben daar kinderen gebaard en ze hebben het eiland Manhattan van de wilden3) gekocht voor 60 gulden (…). Er is koren gezaaid in mei en gemaaid in augustus. Ze hebben voorbeelden van deze zomergranen gestuurd: tarwe, rogge, gerst, haver, boekweit, kanariezaad, bonen en vlas. De lading van het schip is: 7246 bevervellen, 675 ottervellen, 48 nertsvellen.
noot 1 een gebied in Noord-Amerika waar Nederlandse kolonisten zich vestigen noot 2 de Nederlandse kolonisten noot 3 Schaghen bedoelt de oorspronkelijke bevolking.$$, 'inline'),
  ('290c9f16-c099-4356-a7da-b6a4cb4ca644', 'e8589101-9c7b-41ee-8273-50478312ecf0', $$bron 4: abolitionist Carl Wädstrom over een West-Afrikaanse koning (1787)$$,
   $$geschiedenis-havo-2025-ii-pruiken-en-revoluties-bron4.png$$,
   $$bron 4 De abolitionist Carl Wädstrom reist in 1787 naar Afrika en publiceert daarover een boek. Hierin staat over een koning in West-Afrika:
De koning had in het jaar 1787 een wet aangenomen die hem tot eer strekte, namelijk dat geen slaaf meer door zijn rijk mocht worden vervoerd. In die tijd lagen verschillende Franse schepen1) te anker in de Senegalese baai, wachtend op slaven. De route van de handelaren in zwarte mensen was door deze wet van de koning geblokkeerd en ze brachten de slaven daarom naar andere gebieden. De Fransen die hierdoor hun lading niet kregen, klaagden bij de koning. Hij was echter niet onder de indruk van hun klachten en gaf de geschenken terug die de Senegalese Compagnie hem stuurde. Hiervan was ik zelf getuige, en hij [de koning] verklaarde dat alle rijkdommen van de Compagnie hem niet van gedachte zouden doen veranderen.
noot 1 De Franse schepen waren onderdeel van de Senegalese Compagnie, een organisatie waarmee de Fransen handel dreven in Afrika.$$, 'inline'),
  ('afff3f72-81eb-45d5-9036-904a7f7e0a9c', 'e8589101-9c7b-41ee-8273-50478312ecf0', $$bron 5: oproep van Herman Willem Daendels aan de Nederlanders (1794)$$,
   $$geschiedenis-havo-2025-ii-pruiken-en-revoluties-bron5.png$$,
   $$bron 5 De Nederlander Herman Willem Daendels is generaal van de Franse troepen die in 1794 Gelderland binnentrekken. Hij roept de Nederlanders op:
Begin maar met u te wapenen met jachtgeweren, die u veel op de havezaten (landgoederen) en in de herenhuizen zult vinden. En met pieken, hooivorken of ander lang en scherp gereedschap. Vorm compagnieën van 125 mannen en kies kapiteins. Kies niet de rijkste, die mooi gekleed zijn of het best uit hun woorden komen, maar kies diegenen die het beste kunnen vechten. Wij bezorgen u leiders die de oorlog kennen. Wees niet bang dat u jaren soldaat moet blijven. Niemand hoeft langer de wapens te dragen dan de zaak vereist, dat wil zeggen totdat Oranje1) met zijn ''vergulde'' knechten het land uit is.
noot 1 Daendels bedoelt de stadhouder Willem V van Oranje.$$, 'inline'),
  ('c0a4a9cb-344d-4d2d-8d65-5ee8b677055a', '3f99ebdf-07d3-4311-a924-0b07434b6ca3', $$bron 7: dominee Hoedemaker over fabrieksarbeiders in Veenendaal (1875)$$,
   $$geschiedenis-havo-2025-ii-burgers-en-stoommachines-bron7.png$$,
   $$bron 7 In 1875 schrijft dominee Hoedemaker in de brochure De Fabrieksarbeiders te Veenendaal:
Levendig herinner ik mij de indruk, die de bleke, ingevallen, verouderde, scherp getekende gelaatstrekken van de jongens en meisjes (…), op mij
maakten vooral gedurende de eerste weken van mijn verblijf te Veenendaal. Nooit vergeet ik het ongewone geluid van de fabrieksbel, die mij vaak wekte, terwijl alles buiten nog donker en stil was, en hoe ik te midden van de
afgemeten voetstappen der oudere arbeiders, het getrappel van kleine voetjes kon onderscheiden, die zich voorbij de woningen waar alles nog ''in de rust
was'', naar het werk spoedden. Ik wist, dat er kinderen voorbijgingen, die misschien dezen morgen al slapende uit bed getild waren om, op de kille stenen van den vloer wakker geschud, tot bezinning te komen.$$, 'inline'),
  ('ca0da794-f9c8-4a13-8347-65694ebe7727', 'db48578b-640f-42dc-b67b-c6e2edaa9671', $$bron 9: Freiburger Zeitung over de verkiezingsdag in Berlijn (1936)$$,
   $$geschiedenis-havo-2025-ii-duitsland-in-europa-bron9.png$$,
   $$bron 9 Bericht uit de Duitse krant Freiburger Zeitung van 29 maart 1936:
Een prachtige lentehemel glimlacht over de Rijkshoofdstad. Verkiezingsdag - feestdag! De Berlijners werden al vroeg uit bed getrommeld. Sinds 7.00 uur klinkt er marsmuziek door de met vlaggen versierde straten. De nazigelederen zijn overal aanwezig en doen opnieuw een beroep op plicht en geweten (…). Een verkwikkende, vrolijke sfeer domineert de stad. Binnenkort zal er een echte volksverhuizing plaatsvinden naar de meer dan 2.000 stembureaus. (...) Bij aanvang van de verkiezingen, staan er lange rijen mensen voor de stembureaus tot ver in de straten. (...) Om 12.00 uur hebben al vele honderdduizenden hun stem kunnen uitbrengen, stemmend in lijn met de grote woorden van de leider [Hitler] die in veel stembureaus aan de muur hangt: ''voor de één zijn we de partij, voor een ander een organisatie, weer iets anders voor een derde, in werkelijkheid zijn wij het Duitse volk!''$$, 'inline'),
  ('1bd2cf6c-ef3a-4e14-990c-7480c157f512', 'db48578b-640f-42dc-b67b-c6e2edaa9671', $$bron 11: Christel Dux over een grenscontrole in Berlijn (1957)$$,
   $$geschiedenis-havo-2025-ii-duitsland-in-europa-bron11.png$$,
   $$bron 11 Christel Dux beschrijft een voorval uit haar jeugd in Oost-Berlijn in 1957:
Papa nam altijd graag de tijdschriften mee die verboden waren, en hij was vooral dol op de Stern1), die oom Alex2) altijd las. Daarom stopte hij vlak voor de grens, voordat we bij de Oberbaumbrug werden gecontroleerd, altijd één of twee tijdschriften in zijn broek. Na een feestje werd hij overmoedig en stopte een aantal tijdschriften in zijn broek toen hij bij tante Gerda2) was. We namen de trein naar Warschauer Straat en liepen naar de Oberbaumbrug, het was al nacht. Op de Oberbaumbrug stond maar één jonge grenswachter, misschien was de ander net vertrokken of ziek, het waren er in ieder geval altijd twee geweest. Hij wilde onze identiteitsbewijzen zien. Over het algemeen werd gevraagd waar je vandaan kwam, maar deze grenswachter zei niets, stelde alleen de gebruikelijke vraag over tijdschriften. Mijn vader antwoordde een beetje geschokt: ''Nee, wat denkt u, zulke besmette kranten lezen wij niet.'' Precies op dat moment vielen de Sternen uit zijn broekspijpen. Pats, daar lagen ze voor de grenswacht. ''O God, we moeten nu gaan'', dacht ik en natuurlijk was ik bang dat mijn ouders nu opgesloten zouden worden. Smokkel van verboden, provocerende, imperialistische geschriften betekende jarenlang gevangenisstraf. Maar de grenswacht liet ons de tijdschriften oppakken, gaf mijn ouders hun identiteitsbewijs en liet ons gaan. "Ga weg", waren slechts zijn woorden. Ik ben deze persoon nog steeds dankbaar dat hij ons van een verschrikkelijk lot heeft gered.
noot 1 Stern is een West-Duits weekblad. noot 2 Oom Alex en tante Gerda wonen in West-Berlijn.$$, 'inline'),
  ('28d9688d-35da-4d8e-8bee-f571387dfaf4', 'db48578b-640f-42dc-b67b-c6e2edaa9671', $$bron 14: prent van Klaus Stuttmann over de Duitse eenheid (1995)$$,
   $$geschiedenis-havo-2025-ii-duitsland-in-europa-bron14.png$$,
   $$bron 14 Prent van de Duitse tekenaar Klaus Stuttmann uit 1995:
[Afbeelding] Prent in drie delen: een slang met ''West'' slokt een egel met ''Ost'' op, ligt daarna met een bolle buik en kronkelt ten slotte van de pijn doordat de stekels van de egel uit zijn lijf steken.
Toelichting: Op de egel staat Ost (Oosten) en op de slang staat West (Westen). De ondertitel is ''Op de dag van de Duitse eenheid''.$$, 'inline'),
  ('2c111251-529f-472c-9595-5b96f31ec388', '5afdb8b3-8257-4e89-9d75-69b7832ad1ab', $$bron 10: Rie Stroek-Wagenmakers over het inwisselen van een girobetaalkaart (jaren 1950)$$,
   $$geschiedenis-havo-2025-ii-nederland-1948-2008-bron10.png$$,
   $$bron 10 In een interview vertelt de Nederlandse Rie Stroek-Wagenmakers over het inwisselen van een girobetaalkaart1) bij de bank in de jaren 1950:
"Was ik eindelijk aan de beurt na een uur wachten, zegt die man ''waar is de toestemming van uw man?'' Woedend was ik." Bij de slager om de hoek vroeg Rie vervolgens een briefje en schreef zelf een machtiging. "Ik ben bij een ander loket gaan staan en heb mijn geld toch gekregen", lacht ze, nog altijd trots op haar ongehoorzaamheid.
noot 1 Met een girobetaalkaart kon je geld opnemen van een bankrekening$$, 'inline'),
  ('7dfe840a-569d-4dfd-98e6-b2dd121015cd', '5afdb8b3-8257-4e89-9d75-69b7832ad1ab', $$bron 13: advertentie van uitzendbureau Studia in Het Parool (1970)$$,
   $$geschiedenis-havo-2025-ii-nederland-1948-2008-bron13.png$$,
   $$bron 13 In het dagblad Het Parool van 5 juni 1970 staat deze advertentie van Studia: een uitzendbureau en een crèche:
MOEDER uw peuter vindt het fijn om samen met leeftijdsgenootjes in een leuke omgeving:
− te spelen (met goed speelgoed).
− te eten (verantwoord voedsel).
− te slapen (in zijn ''eigen'' bedje). Dit kan in Studia onder toezicht van een deskundige leiding. U vindt het prettig om eens - al is het maar voor een paar weken - uit uw dagelijkse sleur te breken. Uw ''oude'' beroep (steno)-typiste of secretaresse weer eens op te nemen. Uw huishoud- of vakantiebudget aan te vullen. Dat kan via Studia uitzendbureau. Uw kind is uitstekend verzorgd. En u verdient minstens f 140,- netto per week.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('16591a18-f1b6-4db6-b9b2-a6a05db5666d', 'bda149b1-cdf8-410d-96dc-f112443e7d0b', 1,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}, {"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["chronologie", "ontdekkingsreizen", "reformatie", "koningin Victoria", "Eerste Wereldoorlog", "dekolonisatie"]'::jsonb,
   $$Chronologisch ordenen van zes gebeurtenissen over papegaaien uit verschillende tijdvakken.$$,
   $$geschiedenis-havo-2025-ii-door-de-tijd-heen-vraag1.png$$, $$De volgende gebeurtenissen, die te maken hebben met papegaaien, staan in willekeurige volgorde:
1 De Culemborgse graaf Floris I, die zich verzette tegen het Spaanse godsdienstbeleid, voerde zijn papegaai een hostie die klaarlag voor een katholieke eredienst.
2 De ontdekkingsreiziger Christoffel Columbus bracht papegaaien, die hij kreeg van de inheemse bevolking van Amerika, naar Spanje.
3 De roodstaartpapegaai ''Polly'' werd de mascotte van een luchtmachtonderdeel met Nederlandse piloten die voor de Duitsers waren gevlucht naar Engeland.
4 In Vught werden in een woonwijk voor Molukkers die na de onafhankelijkheid van Indonesië naar Nederland waren gekomen, straten genoemd naar de papegaaiensoorten Kastoeri en Lori.
5 Koningin Victoria bezat een papegaai die ''God save the Queen'' [God beware de koningin] kon krijsen.
6 Tijdens de Eerste Wereldoorlog werden in Parijs papegaaien in de top van de Eiffeltoren geplaatst die waarschuwden als ze een vliegtuig hoorden aankomen. 2p 1 Zet de gebeurtenissen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('670e6644-2729-4e0d-8191-1b27fb1751c4', 'bda149b1-cdf8-410d-96dc-f112443e7d0b', 16,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Wereldoorlogen — overig (1900-1950)"}]'::jsonb,
   '["chronologie", "Adenauer", "verzoeningspolitiek", "beurskrach", "machtsovername Hitler", "bezettingszones"]'::jsonb,
   $$Chronologisch ordenen van zes gebeurtenissen uit het leven van Konrad Adenauer.$$,
   $$geschiedenis-havo-2025-ii-door-de-tijd-heen-vraag16.png$$, $$De volgende gebeurtenissen uit het leven van Konrad Adenauer (1876-1967) staan in willekeurige volgorde:
1 Adenauer liet vlaggen met daarop het hakenkruis weghalen die aan Keulse bruggen werden opgehangen voor het bezoek van de nieuwe rijkskanselier Hitler.
2 Adenauer sprak met de Fransen over samenwerking in het Rijnland om de Duitse verzoeningspolitiek te ondersteunen.
3 De leiding van de Britse bezettingszone verweet Adenauer dat hij het opruimen van puin in Keulen niet snel genoeg regelde.
4 Kort nadat legerofficieren een aanslag pleegden op Hitler vanwege het dramatische verloop van de strijd tegen de geallieerden, werd Adenauer opgepakt en vastgezet.
5 Om meer arbeidsplaatsen te creëren voor de mensen die door de beurskrach werkloos werden, verbood Adenauer zijn ambtenaren bijbanen te hebben.
6 Tijdens de Eerste Wereldoorlog ontwikkelde Adenauer een worst op basis van sojameel om het tekort aan vlees op te vangen. 2p 16 Zet deze gebeurtenissen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('f8a8449f-429e-462d-bf16-84cdb8c99d37', 'ce7fda7b-6761-4a3e-a790-ce2ae7385c71', 2,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}]'::jsonb,
   '["renaissance", "humanisme", "klassieke Oudheid", "Latijn", "kenmerkend aspect", "zestiende eeuw"]'::jsonb,
   $$Voor twee kenmerkende aspecten van de zestiende eeuw aantonen dat de mening van Cincius Romanus erbij past.$$,
   $$geschiedenis-havo-2025-ii-ontdekkers-en-hervormers-vraag2.png$$, $$Gebruik bron 1. De mening die Cincius Romanus geeft over de bibliotheek van Sankt Gallen past bij verschillende kenmerkende aspecten van de zestiende eeuw. 2p 2 Toon dit aan voor twee kenmerkende aspecten van de zestiende eeuw. Let op: je moet na het opschrijven van een kenmerkend aspect een uitleg geven.$$, array['51bbe6fd-2e21-43f0-a645-75daf7830d61']::uuid[]),
  ('2cbeea92-6a7a-4c6b-8f24-9e5b0f4ca43c', 'ce7fda7b-6761-4a3e-a790-ce2ae7385c71', 3,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}]'::jsonb,
   '["reformatie", "Maarten Luther", "protestantisme", "godsdienstige onrust", "Opstand", "stadsbestuur"]'::jsonb,
   $$Beredeneren waarom het Groningse stadsbestuur verwachtte dat een boek van Luther voor onrust zou zorgen.$$,
   $$geschiedenis-havo-2025-ii-ontdekkers-en-hervormers-vraag3.png$$, $$Een geschiedenis: In 1557 onderwees schoolmeester Derck Paesschen in Groningen zijn leerlingen uit ''een zeker Duits boekje, namelijk van Maarten Luther''. Het stadsbestuur verbood de schoolmeester dit boek te gebruiken. Toen Paesschen het boek toch bleef gebruiken, werd hij door het stadsbestuur uit Groningen verbannen om onrust te voorkomen. 2p 3 Beredeneer waardoor het stadsbestuur ervan uitging dat het gebruik van een boek van Maarten Luther voor onrust zou zorgen in de stad.$$, array[]::uuid[]),
  ('78a30b75-92a1-47bd-a7f4-a2e60c7adf28', 'ce7fda7b-6761-4a3e-a790-ce2ae7385c71', 4,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["Opstand", "Filips II", "overzeese expansie", "ontdekkingsreizen", "handelsroute naar Azië", "kenmerkend aspect"]'::jsonb,
   $$Twee gebeurtenissen rond de Portugese havens en de Houtman-expeditie verklaren met verschillende kenmerkende aspecten van de zestiende eeuw.$$,
   $$geschiedenis-havo-2025-ii-ontdekkers-en-hervormers-vraag4.png$$, $$Twee gebeurtenissen:
1 Nadat Portugal in 1580 bij Spanje werd gevoegd, besloot de Spaanse koning Filips II dat schepen uit de Republiek niet meer in Portugese havens mochten komen.
2 In 1592 gaven Amsterdamse kooplieden aan de gebroeders Houtman opdracht om informatie in te winnen over de Carreira da Índia, de zeeroute naar India die de Portugezen hadden ontdekt. 2p 4 Geef voor elke gebeurtenis een verklaring met behulp van een verschillend kenmerkend aspect van de zestiende eeuw. Let op: je moet na het opschrijven van een kenmerkend aspect een uitleg geven.$$, array[]::uuid[]),
  ('30004ee6-0417-4378-b8ea-ae9a74fbce2d', '2baaeaa7-e8c2-44f1-9c30-8e173a0b6a88', 7,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["East India Company", "Verdrag van Allahabad", "belastinginning", "Brits-Indisch leger", "propaganda", "medaille"]'::jsonb,
   $$Uitleggen waarom de Britten na 1765 een leger in India nodig hadden en welke boodschap de medaille en de afbeelding erop moesten uitdragen.$$,
   $$geschiedenis-havo-2025-ii-het-britse-rijk-vraag7.png$$, $$Gebruik bron 3. Na 1765 hebben de Britten behoefte aan een leger in India. Deze medaille wordt uitgereikt aan inheemse soldaten die voor de Britten vechten in India. 4p 7 Geef aan:
− waarom de Britten behoefte hebben aan een leger, waarbij je in je antwoord ingaat op een gebeurtenis uit 1765, en
− welke boodschap de Britten willen geven door het uitreiken van de medaille, en
− welke boodschap de Britten willen geven met de afbeelding op de medaille.$$, array['ccd972df-c61a-4271-a5c9-b4930e6d64a5']::uuid[]),
  ('e36b731b-045c-44ab-9400-1c144e5642f1', '2baaeaa7-e8c2-44f1-9c30-8e173a0b6a88', 10,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["afschaffing slavernij", "plantage-economie", "Caribisch gebied", "Wereldtentoonstelling 1851", "industriële revolutie", "stoommachine"]'::jsonb,
   $$De interesse voor een suikerrietpers verklaren vanuit de afschaffing van de slavernij in 1833 en de boodschap van de Wereldtentoonstelling.$$,
   $$geschiedenis-havo-2025-ii-het-britse-rijk-vraag10.png$$, $$In 1851 toonde het Britse bedrijf Robinson and Russel op de wereldtentoonstelling in Londen een stoommachine waarmee suikerriet kon worden geperst. Er was veel interesse voor deze machine. 3p 10 Licht de interesse voor de machine toe door:
− een verklaring te geven waardoor er in het Caribisch gebied interesse was voor machines als deze, waarbij je in je antwoord ingaat op een Brits besluit uit 1833, en
− aan te geven dat het tonen van de machine van Robinson and Russel bijdroeg aan de boodschap die de wereldtentoonstelling moest overbrengen.$$, array[]::uuid[]),
  ('6274183f-3f7b-4859-8bc8-c0359e20fcb8', '2baaeaa7-e8c2-44f1-9c30-8e173a0b6a88', 11,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["Opstand van 1857", "stoomschepen", "modern imperialisme", "industriële revolutie", "Brits gezag in India", "kenmerkend aspect"]'::jsonb,
   $$Verklaren waarom de Britten in 1857 rivierschepen voor India lieten bouwen en bij welk kenmerkend aspect het ontwerp past.$$,
   $$geschiedenis-havo-2025-ii-het-britse-rijk-vraag11.png$$, $$Gebruik bron 6. In 1857 laat de Britse overheid schepen bouwen die speciaal ontworpen zijn voor rivieren in India. De Britse overheid eist dat:
1 de schepen tot ver in de binnenlanden kunnen varen.
2 de schepen veel soldaten tegelijk kunnen vervoeren. 3p 11 Licht de bouw van het schip toe door:
− te verklaren waardoor de Britse overheid juist in 1857 opdracht geeft voor de bouw van schepen als deze, en
− aan te tonen bij welk kenmerkend aspect van de negentiende eeuw het ontwerp van het schip past. Let op: je moet na het opschrijven van een kenmerkend aspect een uitleg geven.$$, array['224c081d-792d-4cbb-b942-f22c5f22934d']::uuid[]),
  ('d1430d33-b474-4290-b8c1-8b573fef9fcc', '2baaeaa7-e8c2-44f1-9c30-8e173a0b6a88', 13,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["modern imperialisme", "beschavingsmissie", "superioriteitsgevoel", "zending", "koloniale expansie", "bronverwijzing"]'::jsonb,
   $$Met de liedtekst aangeven welke kritiek het lied geeft op het Britse idee de wereld te moeten beschaven.$$,
   $$geschiedenis-havo-2025-ii-het-britse-rijk-vraag13.png$$, $$Gebruik bron 8. Eind negentiende eeuw dachten de Britten dat zij de wereld moesten beschaven. 2p 13 Geef aan welke kritiek het lied weergeeft op dit idee, waarna je je antwoord ondersteunt met een verwijzing naar de liedtekst.$$, array['2b08553a-7cd5-49e4-a1f8-e882201da4e0']::uuid[]),
  ('5419067e-6f22-46c0-a675-76c26264c82a', '3121c032-54c5-4142-ac93-daf56e79a885', 5,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}]'::jsonb,
   '["WIC", "Nieuw-Nederland", "vestigingskolonie", "oorspronkelijke bevolking", "Republiek", "bronverwijzing"]'::jsonb,
   $$Met de brief aantonen dat de kolonisten in Nieuw-Nederland hun twee opdrachten uitvoeren.$$,
   $$geschiedenis-havo-2025-ii-regenten-en-vorsten-vraag5.png$$, $$Gebruik bron 2. De kolonisten krijgen twee opdrachten mee voor de stichting van Nieuw-Nederland:
1 Nieuw-Nederland moet een vestigingskolonie worden.
2 De kolonisten moeten ervoor zorgen dat er geen conflicten ontstaan met de oorspronkelijke bevolking. 2p 5 Toon voor elk van beide opdrachten apart aan dat uit de brief blijkt dat de kolonisten deze uitvoeren.$$, array['c8f28811-cffc-45a5-b384-17a2432c1dfc']::uuid[]),
  ('1ac9874a-5558-477f-880c-494509ea1cb3', '3121c032-54c5-4142-ac93-daf56e79a885', 6,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}]'::jsonb,
   '["WIC", "handelskapitalisme", "bonthandel", "winst", "Gouden Eeuw", "bronverwijzing"]'::jsonb,
   $$Vanuit de functie van Schaghen als WIC-bestuurder verklaren waarom hij tevreden is met de kolonie.$$,
   $$geschiedenis-havo-2025-ii-regenten-en-vorsten-vraag6.png$$, $$Gebruik bron 2 nogmaals. Pieter Schaghen is tevreden met de kolonie. 2p 6 Verklaar vanuit zijn functie als bestuurder van de WIC dat Schaghen tevreden is met de kolonie, waarna je je antwoord ondersteunt met een verwijzing naar de bron.$$, array['c8f28811-cffc-45a5-b384-17a2432c1dfc']::uuid[]),
  ('feb8168d-571b-4927-b69e-41c58c688ff6', 'e8589101-9c7b-41ee-8273-50478312ecf0', 8,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["abolitionisme", "slavenhandel", "standplaatsgebondenheid", "Afrikaanse handelaren", "motieven", "bronverwijzing"]'::jsonb,
   $$Met de bron aantonen dat Wädstrom het abolitionisme wil steunen en een niet-abolitionistisch motief van de Afrikaanse koning noemen.$$,
   $$geschiedenis-havo-2025-ii-pruiken-en-revoluties-vraag8.png$$, $$Gebruik bron 4. Historici denken dat:
1 Wädstrom door het opnemen van deze gebeurtenis de abolitionistische beweging wil steunen.
2 de Afrikaanse koning mogelijk niet beïnvloed is door abolitionistische ideeën. 3p 8 Ondersteun beide redeneringen door:
− met een verwijzing naar de bron een argument te geven voor de eerste redenering, en
− zonder bron een motief van de Afrikaanse koning te noemen voor het verbod op het vervoeren van slaafgemaakten door zijn rijk dat niet past bij abolitionistische ideeën.$$, array['290c9f16-c099-4356-a7da-b6a4cb4ca644']::uuid[]),
  ('33d7106c-14be-43f5-bac1-982e701ef21a', 'e8589101-9c7b-41ee-8273-50478312ecf0', 9,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["Verlichting", "democratische revoluties", "patriotten", "Bataafse Revolutie", "gelijkheid", "bronverwijzing"]'::jsonb,
   $$Per kenmerkend aspect uitleggen waarom de oproep van Daendels past bij verlicht denken en bij de democratische revoluties.$$,
   $$geschiedenis-havo-2025-ii-pruiken-en-revoluties-vraag9.png$$, $$Gebruik bron 5. De oproep van Daendels past bij:
1 ''verlicht denken'' dat werd toegepast op sociale verhoudingen''.
2 ''de democratische revoluties in westerse landen''. 4p 9 Geef per kenmerkend aspect aan waarom de oproep hierbij past, waarna je je antwoord telkens ondersteunt met een andere verwijzing naar de bron.$$, array['afff3f72-81eb-45d5-9036-904a7f7e0a9c']::uuid[]),
  ('ab1f5c5a-428f-4712-8d2d-92487b0f2782', '3f99ebdf-07d3-4311-a924-0b07434b6ca3', 12,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["sociale kwestie", "kinderarbeid", "confessionalisme", "fabrieksarbeid", "industriële revolutie", "bronverwijzing"]'::jsonb,
   $$Aantonen dat Hoedemaker bijdraagt aan de discussie over de sociale kwestie en de passende politiek-maatschappelijke stroming noemen.$$,
   $$geschiedenis-havo-2025-ii-burgers-en-stoommachines-vraag12.png$$, $$Gebruik bron 7. Dominee Hoedemaker wil met de brochure geld bij elkaar krijgen voor zijn werkzaamheden, zoals het verzorgen van godsdienstlessen voor fabriekskinderen. 3p 12 Licht dit toe door:
− aan te tonen dat Hoedemaker een bijdrage levert aan ''de discussies rondom de sociale kwestie'', waarna je je antwoord ondersteunt met een verwijzing naar de bron, en
− zonder bron de politiek-maatschappelijke stroming te noemen waarbij Hoedemaker met zijn werkzaamheden past.$$, array['c0a4a9cb-344d-4d2d-8d65-5ee8b677055a']::uuid[]),
  ('ca84b436-fced-4bd7-9221-43bde195f8e6', '3f99ebdf-07d3-4311-a924-0b07434b6ca3', 25,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["modern imperialisme", "Nederlands-Indië", "oorlogsbuit", "koloniale expansie", "nationalisme", "kenmerkend aspect"]'::jsonb,
   $$Het tentoonstellen van de diamant van Banjarmasin verklaren met het moderne imperialisme en de politieke boodschap ervan noemen.$$,
   $$geschiedenis-havo-2025-ii-burgers-en-stoommachines-vraag25.png$$, $$De volgende vraag gaat over de diamant van Banjarmasin, die werd meegenomen van het Indonesische eiland Borneo naar Nederland:
In 1859 veroverden Nederlandse troepen het vorstendom Banjarmasin op het Indonesische eiland Borneo. Ze namen een grote diamant van de voormalige sultan van Banjarmasin mee. De Nederlandse regering liet deze diamant in het Rijksmuseum tentoonstellen, als ''een geschiedkundig gedenkteken van de onderwerping van Banjarmasin''. 2p 25 Licht het tentoonstellen van de diamant toe door:
− met een kenmerkend aspect uit de negentiende eeuw een verklaring te geven voor de beslissing om de diamant tentoon te stellen, en
− de politieke boodschap te noemen die de regering met het tentoonstellen wilde overbrengen. Let op: je moet na het opschrijven van een kenmerkend aspect een uitleg geven.$$, array[]::uuid[]),
  ('fd26f6c7-a8c8-45dd-8cee-9ecc4e54b647', 'db48578b-640f-42dc-b67b-c6e2edaa9671', 14,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["Republiek van Weimar", "Freikorps", "dolkstootlegende", "zwakke democratie", "Verdrag van Versailles", "leger"]'::jsonb,
   $$Aan de geschiedenis van de Vrijkorpsen twee oorzaken ontlenen voor de zwakke positie van de Weimarregering.$$,
   $$geschiedenis-havo-2025-ii-duitsland-in-europa-vraag14.png$$, $$Een geschiedenis: Begin 1919 sloten meer dan 350.000 Duitse soldaten zich aan bij paramilitaire eenheden die Freikorps [Vrijkorps] werden genoemd. De regering van de Republiek van Weimar zette Vrijkorpsen eerst in voor het neerslaan van opstanden, maar kondigde in 1920 aan dat ze werden opgeheven. Hierna kwamen Vrijkorpsen in opstand. De Duitse legerleiding weigerde de opstand neer te slaan. Aan deze geschiedenis kun je verschillende oorzaken ontlenen voor de zwakke positie van de regering van de Republiek van Weimar. 2p 14 Toon dit voor twee oorzaken aan.$$, array[]::uuid[]),
  ('e3cbf9b0-3b16-4786-b4ba-ee8b81b303bc', 'db48578b-640f-42dc-b67b-c6e2edaa9671', 15,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["totalitarisme", "propaganda", "gelijkgeschakelde pers", "verkiezingen", "betrouwbaarheid", "bronverwijzing"]'::jsonb,
   $$Uitleggen waarom Duitse krantenartikelen uit 1936 onbetrouwbaar kunnen zijn maar de beschrijving wel past bij een verkiezingsdag in een totalitaire staat.$$,
   $$geschiedenis-havo-2025-ii-duitsland-in-europa-vraag15.png$$, $$Gebruik bron 9. Stel: je doet onderzoek naar de verkiezingsdag in 1936. Je trekt de conclusie dat deze beschrijving een waarheidsgetrouw beeld geeft van het verloop van de verkiezingsdag. 3p 15 Geef aan:
− zonder bron waardoor je kunt twijfelen aan de betrouwbaarheid van krantenartikelen in Duitsland in die tijd, maar
− dat de beschrijving wel een waarheidsgetrouw beeld geeft van het verloop van een verkiezingsdag in een totalitaire staat, waarna je je antwoord ondersteunt met een verwijzing naar de bron.$$, array['ca0da794-f9c8-4a13-8347-65694ebe7727']::uuid[]),
  ('a6583475-94a9-4b97-b44d-768cc8e51fc7', 'db48578b-640f-42dc-b67b-c6e2edaa9671', 18,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["Berlijnse Muur", "DDR", "vlucht naar het Westen", "grensbewaking", "Staatssicherheitsdienst", "bronverwijzing"]'::jsonb,
   $$Met de bron een motief voor de bouw van de Berlijnse Muur aantonen en verklaren waarom er altijd twee grenswachten werkten.$$,
   $$geschiedenis-havo-2025-ii-duitsland-in-europa-vraag18.png$$, $$Gebruik bron 11. Je concludeert dat je deze bron kunt gebruiken om:
1 een motief aan te tonen voor de bouw van de Berlijnse Muur.
2 te verklaren dat er altijd twee grenswachten tegelijk werken bij de Berlijnse Muur. 4p 18 Toon de juistheid van elke conclusie aan, waarbij je je antwoord telkens ondersteunt met een andere verwijzing naar de bron.$$, array['1bd2cf6c-ef3a-4e14-990c-7480c157f512']::uuid[]),
  ('02c4a807-c3c1-4954-abeb-e2d56ee1166d', 'db48578b-640f-42dc-b67b-c6e2edaa9671', 24,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["Duitse hereniging", "integratie voormalige DDR", "Ost en West", "spotprent", "economische problemen", "bronverwijzing"]'::jsonb,
   $$Met de prent aantonen welke mening de tekenaar heeft over de integratie van de voormalige DDR.$$,
   $$geschiedenis-havo-2025-ii-duitsland-in-europa-vraag24.png$$, $$Gebruik bron 14. De tekenaar geeft in deze prent een mening weer over de integratie van de voormalige DDR in het verenigde Duitsland. 2p 24 Toon aan welke mening dat is, waarna je je antwoord ondersteunt met een verwijzing naar de prent.$$, array['28d9688d-35da-4d8e-8bee-f571387dfaf4']::uuid[]),
  ('ea2459f1-38a5-4a24-afc9-de127b3a6585', '5afdb8b3-8257-4e89-9d75-69b7832ad1ab', 17,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["handelingsonbekwaamheid", "positie van vrouwen", "gehuwde vrouw", "emancipatie", "wetgeving 1956", "bronverwijzing"]'::jsonb,
   $$De wet uit 1956 noemen die de beschreven situatie onmogelijk maakte en met de bron aangeven wat die wet veranderde.$$,
   $$geschiedenis-havo-2025-ii-nederland-1948-2008-vraag17.png$$, $$Gebruik bron 10. De situatie die Rie Stroek-Wagenmakers beschrijft, vindt na 1956 niet meer plaats in Nederland. 2p 17 Geef hiervoor een verklaring door:
− de wet uit 1956 te noemen die situaties als deze niet langer mogelijk maakt, en
− met een verwijzing naar de bron aan te geven wat deze wet wil veranderen.$$, array['2c111251-529f-472c-9595-5b96f31ec388']::uuid[]),
  ('0d176b87-11a9-4072-b435-01c6096f394d', '5afdb8b3-8257-4e89-9d75-69b7832ad1ab', 21,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["tweede feministische golf", "rolpatronen", "economische groei", "vrouwenarbeid", "consumptiemaatschappij", "bronverwijzing"]'::jsonb,
   $$Met de advertentie aantonen dat tweede-golffeministen kritiek zouden hebben en dat het succes van uitzendbureaus samenhing met economische groei.$$,
   $$geschiedenis-havo-2025-ii-nederland-1948-2008-vraag21.png$$, $$Gebruik bron 13. Twee beweringen:
1 Feministen van de tweede golf zullen kritiek hebben op deze advertentietekst.
2 Het succes van uitzendbureaus als Studia wordt mede veroorzaakt door de groei van de economie in Nederland. 4p 21 Toon de juistheid van beide beweringen aan, waarna je je antwoord telkens ondersteunt met een verwijzing naar de bron.$$, array['7dfe840a-569d-4dfd-98e6-b2dd121015cd']::uuid[]),
  ('8889dbb6-2041-4f12-a1de-eb34b2648f46', '5afdb8b3-8257-4e89-9d75-69b7832ad1ab', 22,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}]'::jsonb,
   '["Lubbers", "kritiek op verzorgingsstaat", "bezuinigingen", "no-nonsensebeleid", "eigen verantwoordelijkheid", "CDA"]'::jsonb,
   $$Met het CDA-rapport aantonen welke beleidsmaatregel Lubbers wilde ondersteunen.$$,
   $$geschiedenis-havo-2025-ii-nederland-1948-2008-vraag22.png$$, $$Een gegeven: In 1983 publiceerde het Christen-Democratisch Appèl (CDA), de partij van minister-president Lubbers, een onderzoeksrapport. Hierin stond de kritiek dat burgers "in plaats van voor elkaar te zorgen, er steeds meer vanuit gaan dat de overheid die verantwoordelijkheid overneemt." Lubbers wilde met dit onderzoeksrapport zijn beleid ondersteunen. 2p 22 Toon met een verwijzing naar het onderzoeksrapport aan welke beleidsmaatregel Lubbers wilde ondersteunen.$$, array[]::uuid[]),
  ('dbee19b1-6282-4439-93c3-c9c21fc03aff', '5afdb8b3-8257-4e89-9d75-69b7832ad1ab', 23,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}]'::jsonb,
   '["migrantenbeleid", "gastarbeiders", "terugkeergedachte", "multiculturele samenleving", "onderwijs in eigen taal", "integratie"]'::jsonb,
   $$Uitleggen bij welk migrantenbeleid het besluit uit 1984 over les in de eigen taal paste.$$,
   $$geschiedenis-havo-2025-ii-nederland-1948-2008-vraag23.png$$, $$In 1984 besloot de Nederlandse regering dat op lagere scholen aan "leerlingen van ''niet-Nederlandse afkomst'' les zal worden gegeven in hun eigen taal, zoals het Turks, Marokkaans, Italiaans, Grieks en Moluks." 2p 23 Leg uit bij welk migrantenbeleid van de overheid in die tijd dit besluit paste.$$, array[]::uuid[]),
  ('31f10734-441b-4f76-bec6-a2bd41b51490', 'e6720cf1-6d6d-4cf6-9d4b-64564cb66c37', 19,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["ontzuiling", "verzuiling", "katholieke zuil", "secularisatie", "pers", "jaren zestig"]'::jsonb,
   $$Uitleggen bij welke maatschappelijke verandering het schrappen van de katholieke ondertitel van de Volkskrant past.$$,
   $$geschiedenis-havo-2025-ii-computer-en-televisie-vraag19.png$$, $$Na de Tweede Wereldoorlog verscheen de Volkskrant met de ondertitel ''Katholiek dagblad voor Nederland''. In 1965 besloot de redactie van de Volkskrant om de ondertitel niet meer te gebruiken. 2p 19 Leg uit bij welke maatschappelijke verandering in Nederland in de tweede helft van de twintigste eeuw dit besluit past.$$, array[]::uuid[]),
  ('211ab827-ec52-42e0-a242-55f71dc187f2', 'e6720cf1-6d6d-4cf6-9d4b-64564cb66c37', 26,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}, {"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}]'::jsonb,
   '["dekolonisatie", "koloniaal verleden", "oorlogsbuit", "restitutie", "multiculturele samenleving", "kenmerkend aspect"]'::jsonb,
   $$Het plaatsen van een tekst over oorlogsbuit bij de diamant van Banjarmasin verklaren met een kenmerkend aspect uit de twintigste eeuw.$$,
   $$geschiedenis-havo-2025-ii-computer-en-televisie-vraag26.png$$, $$De volgende vraag gaat over de diamant van Banjarmasin, die werd meegenomen van het Indonesische eiland Borneo naar Nederland:
In 2017 plaatste het Rijksmuseum bij de diamant van Banjarmasin (zie vraag 25) de tekst: "Deze diamant is oorlogsbuit. Ooit was hij eigendom van Panembahan Adam, de sultan van Banjarmasin". 2p 26 Licht het plaatsen van de tekst toe door:
− met een kenmerkend aspect uit de twintigste eeuw een verklaring te geven voor het besluit deze tekst te plaatsen, en
− aan te geven wat het Rijksmuseum met de tekst wilde bereiken. Let op: je moet na het opschrijven van een kenmerkend aspect een uitleg geven.$$, array[]::uuid[]);
